const startPlayback=(all=false)=>{const start=all?(run.allPages?0:Math.min(project.pages.length-1,Math.max(0,run.startPage-1))):pi;sequence.current=all;playCursor.current={index:start,time:0,cycle:1};setPi(start);setTime(0);setOutputClear(false);setPlaying(true)};
