const loadProject=(data:unknown,ref:{id:string;revision:number}|null=null)=>{const parsed=normalizeProject(data);if(!parsed){msg('프로젝트 형식이 올바르지 않습니다. CG 편집기의 프로젝트 파일을 선택하세요.');return false}if(dirty&&!window.confirm('현재 변경 내용을 바꾸고 프로젝트를 열까요? 저장하지 않은 내용은 실행 취소로 복구할 수 있습니다.'))return false;setHistory(h=>[...h.slice(-39),projectRef.current]);setFuture([]);projectRef.current=parsed;setProject(parsed);setPi(0);setSelection([]);setRange({start:0,end:0});setTime(0);setPlaying(false);setDirty(false);setSavedRef(ref);setModal(null);setDownload(null);msg('프로젝트 불러오기 완료');generation.current++;return true};
const portable=async(snapshot:Project)=>{const result=structuredClone(snapshot);const sources=new Map<string,string>();for(const items of projectMedia(result))for(const i of items){if(i.src?.startsWith('/api/media/')){let src=sources.get(i.src);if(!src){const r=await fetch(i.src,{credentials:'same-origin'});if(!r.ok)throw Error('이미지·영상·음성을 포함하지 못했습니다. 원본 파일을 다시 연결해주세요.');const blob=await r.blob();src=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result as string);reader.onerror=reject;reader.readAsDataURL(blob)});sources.set(i.src,src)}i.src=src}}return result};
const saveJSON=async()=>{if(busy)return;const snapshot=structuredClone(projectRef.current),version=generation.current;let handle:any=null;try{if('showSaveFilePicker'in window)handle=await (window as any).showSaveFilePicker({suggestedName:jsonFile(snapshot.name),types:[{description:'CG 프로젝트',accept:{'application/json':['.json']}}]})}catch(e){if((e as Error).name==='AbortError')return}setBusy(true);msg('미디어를 포함한 프로젝트 파일을 준비합니다…');try{const data=await portable(snapshot),text=JSON.stringify(data,null,2);if(handle){const writer=await handle.createWritable();await writer.write(text);await writer.close();const savedFile=await handle.getFile();if(!normalizeProject(JSON.parse(await savedFile.text())))throw Error('저장 파일 검증에 실패했습니다.');if(generation.current===version)setDirty(false);msg('프로젝트 파일 저장 완료');setModal(null)}else{const blob=new Blob([text],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob);setDownload({url,name:jsonFile(snapshot.name)});setModal('save');msg('프로젝트 파일 준비 완료 · 대화창의 내려받기를 누르세요.')}}catch(e){msg((e as Error).message||'프로젝트 저장에 실패했습니다. 작업 내용은 유지됩니다.')}finally{setBusy(false)}};
const api=async(url:string,options?:RequestInit)=>{const r=await fetch(url,{credentials:'same-origin',...options});let data:any;try{data=await r.json()}catch{throw Error('저장 서비스가 응답하지 않습니다. 프로젝트 파일 저장을 사용하세요.')}if(!r.ok)throw Error(data.error||'요청에 실패했습니다.');return data};
const refreshSaved=async()=>{try{const d=await listProjectFiles();setSaved(d.projects.map(p=>({id:p.name,name:p.name,revision:0,updated:p.updated})))}catch(e){msg((e as Error).message)}};
const saveServer=async(confirmOverwrite=false)=>{if(busy)return;setBusy(true);const snapshot=structuredClone(projectRef.current),version=generation.current;msg('bin/project 에 저장합니다…');try{
  // 일반 저장(Ctrl+S, confirmOverwrite=false)은 항상 원래 열었던 파일(savedRef.id)에 덮어쓴다.
  // 화면에 보이는 project.name 이 파일명과 달라도(이름을 바꿨거나 둘이 어긋난 기존 파일) 엉뚱한 파일이 새로 생기지 않게 함.
  // "다른 이름으로 저장"(confirmOverwrite=true)일 때만 지금 이름으로 새 파일명을 정한다.
  // 공백도 허용 안 함: 이름에 공백이 섞여 있으면 실제 파일명과 어긋나기 쉬우므로 '_' 로 치환.
  const target=(!confirmOverwrite&&savedRef)?savedRef.id:snapshot.name.trim().replace(/[\\/:*?"<>|\x00-\x1f\s]+/g,'_');
  snapshot.name=target;   // 내부 name 필드도 파일명과 항상 같게 맞춰서(공백 등) 다음 저장 때 다시 어긋나지 않게 함
  if(confirmOverwrite){if((await listProjectFiles()).projects.some(p=>p.name===target)&&!window.confirm('"'+target+'" 프로젝트가 이미 있습니다. 덮어쓸까요?')){msg('저장을 취소했습니다');return}}
  const result=await saveProjectFile(target,snapshot);setSavedRef({id:result.name,revision:0});if(generation.current===version){projectRef.current=result.project;setProject(result.project);setDirty(false)}msg('bin/project/'+result.name+'.json 저장 완료'+(result.extractedMedia?' · 포함된 미디어 '+result.extractedMedia+'개를 bin/media 로 옮겼습니다':''));await refreshSaved();setModal(null)}catch(e){msg((e as Error).message)}finally{setBusy(false)}};
const openSaved=async(s:Saved)=>{setBusy(true);try{loadProject(await loadProjectFile(s.id),{id:s.id,revision:0})}catch(e){msg((e as Error).message)}finally{setBusy(false)}};
const importMedia=async(name:string,kind:Kind)=>{setBusy(true);msg('미디어를 불러옵니다…');try{const src=mediaRef(name);let width=800,height=450,duration=10;if(kind==='image'){const image=new Image();image.src=mediaUrl(src);await image.decode();width=Math.min(W,image.naturalWidth);height=width*image.naturalHeight/image.naturalWidth}else{const media=document.createElement(kind==='video'?'video':'audio');media.preload='metadata';media.src=mediaUrl(src);await new Promise<void>((resolve,reject)=>{media.onloadedmetadata=()=>resolve();media.onerror=()=>reject(Error('브라우저가 지원하지 않는 영상·음성 형식입니다. MP4·WebM 또는 MP3·WAV로 변환해주세요.'))});duration=Math.min(3600,Number.isFinite(media.duration)?media.duration:10);if(kind==='video'){const v=media as HTMLVideoElement;width=Math.min(1200,v.videoWidth||800);height=width*(v.videoHeight||450)/(v.videoWidth||800)}media.removeAttribute('src');media.load()}const current=projectRef.current,p=current.pages[piRef.current],o=make(kind,{name,src,w:width,h:height,x:kind==='audio'?0:100,y:kind==='audio'?0:100,duration,start:0});commit({...current,pages:current.pages.map((pg,n)=>n===piRef.current?{...pg,duration:Math.max(pg.duration,duration),items:[...pg.items,o]}:pg)});setSelection([o.id]);msg(name+' 불러오기 완료')}catch(e){msg((e as Error).message)}finally{setBusy(false)}};
const addHdmiVideo=()=>{const current=projectRef.current,p=current.pages[piRef.current],o=make('video',{name:'HDMI 입력',src:'hdmirx',x:0,y:0,w:1920,h:1080,duration:p.duration,start:0});commit({...current,pages:current.pages.map((pg,n)=>n===piRef.current?{...pg,items:[...pg.items,o]}:pg)});setSelection([o.id]);msg('HDMI 입력(라이브)을 추가했습니다 · 미리보기 화면에는 안 보이고 실행엔진(cg-streamer)에서만 재생됩니다')};
const removeSaved=async(s:Saved)=>{if(busy)return;if(s.id===savedRef?.id){msg('현재 열려 있는 프로젝트는 삭제할 수 없습니다');return}if(!window.confirm('"'+s.name+'" 프로젝트를 삭제할까요?\n삭제하면 되돌릴 수 없습니다.'))return;setBusy(true);try{await deleteProjectFile(s.id);msg('"'+s.name+'" 프로젝트를 삭제했습니다');await refreshSaved()}catch(e){msg((e as Error).message)}finally{setBusy(false)}};
const dropMedia=async(name:string,kind:Kind)=>{try{const d=await listMedia(kind as MediaFile['kind']);if(d.files.some(m=>m.name===name))importMedia(name,kind);else msg(name+' 은(는) bin/media 에 없습니다. 파일을 bin/media 폴더에 넣은 뒤 이미지·동영상 버튼으로 선택하세요.')}catch(e){msg((e as Error).message)}};
