const linkText=async()=>{if(!item)return;try{if('showOpenFilePicker'in window){const [handle]=await (window as any).showOpenFilePicker({multiple:false,types:[{description:'텍스트 파일',accept:{'text/plain':['.txt']}}]});const f=await handle.getFile(),text=await f.text();linkHandles.current.set(item.id,handle);batchPatch({[item.id]:{text,linkName:f.name,runs:[]}});msg('텍스트 파일 연결됨 · 변경 내용을 자동으로 확인합니다')}else linkInput.current?.click()}catch(e){if((e as Error).name!=='AbortError')linkInput.current?.click()}};
useEffect(()=>{const id=setInterval(async()=>{if(document.hidden||!linkHandles.current.size)return;for(const [id,h]of linkHandles.current){try{const text=await (await h.getFile()).text();const i=projectRef.current.pages[piRef.current].items.find(i=>i.id===id);if(i&&i.text!==text)batchPatch({[id]:{text,runs:[]}},true)}catch{linkHandles.current.delete(id);msg('텍스트 연결이 끊겼습니다. Text Link에서 다시 연결하세요.')}}},2000);return()=>clearInterval(id)},[batchPatch]);
const exportPNG=()=>{setPlaying(false);setEditId(null);setTimeout(()=>{try{const url=exporter.current?.();if(!url)throw Error('편집 화면이 준비되지 않았습니다.');const a=document.createElement('a');a.href=url;a.download=page.name+'.png';document.body.appendChild(a);a.click();a.remove();msg('PNG 내보내기 · 1920 × 1080')}catch(e){msg((e as Error).message)}},120)};
useEffect(()=>{if(!menu)return;const close=(e:PointerEvent)=>{if(!(e.target as Element)?.closest?.('.menugroup'))setMenu(null)},esc=(e:KeyboardEvent)=>{if(e.key==='Escape')setMenu(null)};const evs=['pointerdown','mousedown','touchstart'] as const;evs.forEach(n=>document.addEventListener(n,close as EventListener,true));const blur=()=>setMenu(null);window.addEventListener('blur',blur);window.addEventListener('keydown',esc);return()=>{window.removeEventListener('blur',blur);evs.forEach(n=>document.removeEventListener(n,close as EventListener,true));window.removeEventListener('keydown',esc)}},[menu]);
const openModal=(m:'open'|'save'|'help')=>{setModal(m);setMenu(null);if(m==='open'){setOpenFilter('');refreshSaved()}};
const shownSaved=saved.filter(s=>s.name.toLowerCase().includes(openFilter.trim().toLowerCase()));
useEffect(()=>{const key=(e:KeyboardEvent)=>{if((e.target as HTMLElement).matches('input,textarea,select,[contenteditable]'))return;const ctrl=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(ctrl&&k==='s'){e.preventDefault();e.shiftKey?openModal('save'):saveServer(!savedRef)}else if(ctrl&&k==='o'){e.preventDefault();openModal('open')}else if(ctrl&&k==='z'){e.preventDefault();e.shiftKey?redo():undo()}else if(ctrl&&k==='y'){e.preventDefault();redo()}else if(ctrl&&k==='a'){e.preventDefault();setSelection(page.items.filter(i=>!i.locked).map(i=>i.id))}else if(ctrl&&k==='c'){e.preventDefault();e.shiftKey?copyPage():copy()}else if(ctrl&&k==='x'){e.preventDefault();if(e.shiftKey){copyPage();removePage()}else{copy();remove()}}else if(ctrl&&k==='v'){e.preventDefault();e.shiftKey?pastePage():paste()}else if(ctrl&&k==='d'){e.preventDefault();duplicate()}else if(ctrl&&k==='g'){e.preventDefault();e.shiftKey?ungroup():group()}else if(e.key==='Delete'){e.preventDefault();remove()}else if(e.key==='Escape'){setSelection([]);setContext(null);setMenu(null);setEditId(null)}else if(e.key==='PageDown'||e.key==='PageUp'){e.preventDefault();setPi(n=>Math.max(0,Math.min(project.pages.length-1,n+(e.key==='PageDown'?1:-1))));setSelection([]);setTime(0);setPlaying(false)}else if(e.altKey&&k==='n'){e.preventDefault();newPage(true)}else if(e.key==='F5'&&ctrl){e.preventDefault();sequence.current=false;setTime(0);setPlaying(true)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selection.length){e.preventDefault();const step=e.altKey||e.shiftKey?10:1;batchPatch(Object.fromEntries(page.items.filter(i=>selection.includes(i.id)&&!i.locked&&!i.fixed).map(i=>[i.id,{x:i.x+(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0),y:i.y+(e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0)}])),true)}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)});

const [rows,setRowsState]=useState<{b:number}|null>(null);const gridRef=useRef<HTMLDivElement>(null);const rowDrag=useRef<{y:number;b:number}|null>(null);
const setRows=(r:{b:number}|null)=>{setRowsState(r);try{r?localStorage.setItem('cg-rows-v4',JSON.stringify(r)):localStorage.removeItem('cg-rows-v4')}catch{}};
const measureRows=()=>{const g=gridRef.current;if(!g)return;const r=getComputedStyle(g).gridTemplateRows.split(' ').map(parseFloat);if(r.length===2&&r.every(Number.isFinite))setRowsState({b:Math.round(r[1])})};
useEffect(()=>{try{const r=JSON.parse(localStorage.getItem('cg-rows-v4')||'null');if(r&&typeof r.b==='number'&&r.b>=100&&r.b<=2000){setRowsState({b:r.b});return}}catch{}measureRows()},[]);
const splitDown=(e:React.PointerEvent<HTMLDivElement>)=>{if(!rows)return;e.currentTarget.setPointerCapture(e.pointerId);rowDrag.current={y:e.clientY,b:rows.b}};
const splitMove=(e:React.PointerEvent<HTMLDivElement>)=>{const d=rowDrag.current;if(!d)return;const dy=e.clientY-d.y,total=(e.currentTarget.parentElement?.clientHeight||900)-14-150;setRows({b:Math.round(Math.max(100,Math.min(total,d.b-dy)))})};
